def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute form, following symlinks.

    Args:
        path: Path to resolve (absolute or relative to cwd)
        cwd: Current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        Canonical absolute path, or None on error
    """
    # Track symlinks followed to prevent infinite loops
    symlinks_followed = 0
    MAX_SYMLINKS = 8

    # Convert relative path to absolute
    if not path.startswith('/'):
        if not cwd.startswith('/'):
            return None
        path = cwd + '/' + path if cwd != '/' else '/' + path

    # Split path into components
    components = path.split('/')

    # Start with root
    current = '/'

    # Process each component
    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory (but not above root)
            if current != '/':
                # Remove the last component
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this path is a symlink
        while candidate in links:
            symlinks_followed += 1
            if symlinks_followed > MAX_SYMLINKS:
                return None

            # Get the symlink target
            target = links[candidate]

            # If target is absolute, start from root
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')
            else:
                # Target is relative to the directory containing the symlink
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Process target components
            for target_comp in target_components:
                if target_comp == '' or target_comp == '.':
                    continue

                if target_comp == '..':
                    if current != '/':
                        current = current.rsplit('/', 1)[0]
                        if current == '':
                            current = '/'
                    continue

                # Append component
                if current == '/':
                    candidate = '/' + target_comp
                else:
                    candidate = current + '/' + target_comp

            # After processing target, candidate might be a symlink itself
            # The while loop will check this

        # Update current to the resolved candidate
        current = candidate

    # Return the result, removing trailing slash except for root
    if current == '/':
        return '/'
    else:
        return current

